const fs = require('fs');

for (const file of ['README.md', 'notes.txt']) {
  const text = fs.readFileSync(file, 'utf8');
  // Count lines: number of newline-terminated lines, plus a final unterminated line if present.
  const lines = text.split('\n');
  if (lines[lines.length - 1] === '') lines.pop();
  console.log(`${file}: ${lines.length} line(s)`);
}

